using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class VoyageExpenseTests
{
    internal static readonly EntityId Player=new("created:voyager");
    internal static string Island=>"iki";
    internal static string Mainland=>NationalRoutes.Edges.Where(e=>NationalRoutes.Sea(e.Id)&&(e.From==Island||e.To==Island)).Select(e=>e.From==Island?e.To:e.From).First(n=>NationalRoutes.Edges.Any(e=>!NationalRoutes.Sea(e.Id)&&(e.From==n||e.To==n)));
    internal static ContractWorld New(long price=10,bool enabled=true)
    {
        var p=new RegisteredOfficer(Player.Value,null,"渡海の検証武将",1520,new(50,50,50,50),StartTemplate.Ronin,RegionalCampaign.Site(Island).Value,null,null);
        var rows=NewGameWorld.Normalize([p]);var preview=NewGameSetup.Preview(NewGameWorld.Scenario(HistoricalStartCatalog.Current),new(rows,[]));Assert.True(preview.IsEligible(),string.Join(";",preview.Errors));
        return NewGameWorld.Create(preview.World!,rows,Player.Value,42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:NewGameWork.Policy,voyageRules:enabled?VoyageExpense.Standard with{FarePerPassage=price}:null);
    }
    internal static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    internal static BranchJourney Start(WorldSession s,string to,bool walk=false){var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:voyage/"+s.Revision,to,walk);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);At(s,s.Seconds+2);return s.DiagnosticSnapshot().Branches!.Journeys.Last();}
    static long BoardAt(WorldSession s,BranchJourney j){var l=j.Legs.First(l=>NationalRoutes.Sea(l.Edge));return TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt);}
    static WorldSession Arrive(long price=10){var s=new WorldSession(New(price));var j=Start(s,Mainland);At(s,j.Legs[^1].EndAt+2);return s;}
    [Fact]public void NewPolicyPinsFareAndPortControlWithoutMakingAnInitialPayment(){var w=New();Assert.Equal(10,w.NewGame!.VoyageRules!.FarePerPassage);Assert.NotNull(w.TravelDecisions);Assert.NotNull(w.TrafficStops);Assert.Null(w.VoyageExpenses);Assert.Equal(1000,NewGameWork.Balance(w,Player));}
    [Fact]public void OldProfileAndLiteralSavesOmitFareFields(){var w=New(enabled:false);Assert.DoesNotContain("VoyageRules",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w)));Assert.Null(w.VoyageExpenses);Assert.Null(w.TravelDecisions);Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(w).DiagnosticSnapshot()));foreach(var n in new[]{"initial","active"}){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","military-bd631ba-"+n+".json"));Assert.Equal(bytes,ContractJson.Write(ContractJson.Read<ContractWorld>(bytes)));}}
    [Fact]public void WaitingAtPortDoesNotCharge(){var s=new WorldSession(New());var j=Start(s,Mainland);At(s,BoardAt(s,j)-1);Assert.True(TravelControl.PortWaiting(s.DiagnosticSnapshot(),Player));Assert.Null(s.DiagnosticSnapshot().VoyageExpenses);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));}
    [Fact]public void ExactBoardingChargesOnceAndIsConservedInOperatorAccount(){var s=new WorldSession(New());var j=Start(s,Mainland);var at=BoardAt(s,j);At(s,at);var w=s.DiagnosticSnapshot();var p=Assert.Single(w.VoyageExpenses!.Payments);Assert.Equal(at,p.At);Assert.Equal(10,p.Amount);Assert.Equal(990,NewGameWork.Balance(w,Player));At(s,at+1);Assert.Single(s.DiagnosticSnapshot().VoyageExpenses!.Payments);Assert.Equal(w.ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.InitialQuantity),w.ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.Quantity)+10);}
    [Fact]public void OriginalTripRetryDoesNotChargeBeforeOrAfterBoarding(){var s=new WorldSession(New());var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:once",Mainland);s.Submit(i,s.Revision);Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,0).Code);At(s,3601);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,0).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().VoyageExpenses!.Payments);}
    [Fact]public void CancellationBeforeDepartureDoesNotCharge(){var s=new WorldSession(New());Start(s,Mainland);var req=TravelControl.Request(s.DiagnosticSnapshot(),"request:cancel-boarding",null);Assert.Equal(ResultCode.Accepted,s.ChangeTravel(req,s.Revision).Code);At(s,5000);Assert.Null(s.DiagnosticSnapshot().VoyageExpenses);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));Assert.Equal(RegionalCampaign.Site(Island),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Player).Site);}
    [Fact]public void UnknownServiceSuspensionStopsLocallyWithoutCharge(){var w=New();w.Couriers=w.Couriers! with{Conditions=NationalRoutes.Edges.Where(e=>NationalRoutes.Sea(e.Id)&&(e.From==Island||e.To==Island)).Select(e=>new RoadCondition(1,e.Id,true)).ToArray()};var s=new WorldSession(w);Start(s,Mainland);At(s,5000);Assert.Null(s.DiagnosticSnapshot().VoyageExpenses);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));Assert.Contains(s.DiagnosticSnapshot().TrafficStops!,t=>t.Reason=="service-suspended");}
    [Fact]public void MissingFundsStopsAtPortWithoutUsingOtherWallets(){var s=Arrive(1000);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));var j=Start(s,Island);At(s,BoardAt(s,j)+1);var w=s.DiagnosticSnapshot();Assert.Equal(0,NewGameWork.Balance(w,Player));Assert.Single(w.VoyageExpenses!.Payments);Assert.Equal(0,Assert.Single(w.VoyageExpenses.Refusals).Available);Assert.Contains(w.TrafficStops!,t=>t.Reason=="fare-insufficient");Assert.Equal(RegionalCampaign.Site(Mainland),w.Locations.Single(l=>l.Actor==Player).Site);Assert.All(w.ResourceLots.Where(l=>NewGameWork.IsWallet(w,l)&&l.Owner!=Player),l=>Assert.Equal(1000,l.Quantity));}
    [Fact]public void ZeroCoinsStillAllowsExplicitLandRoute(){var s=Arrive(1000);var sea=Start(s,Island);At(s,BoardAt(s,sea)+1);var w=s.DiagnosticSnapshot();var e=BranchRoutes.GraphEdges(w).First(e=>!NationalRoutes.Sea(e.Id)&&(e.From==Mainland||e.To==Mainland));var to=e.From==Mainland?e.To:e.From;var j=Start(s,to,true);Assert.All(j.Legs,l=>Assert.False(NationalRoutes.Sea(l.Edge)));At(s,j.Legs[^1].EndAt+2);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));Assert.Equal(RegionalCampaign.Site(to),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Player).Site);}
    [Fact]public void WalkModeCannotCrossOpenWaterAndDoesNotLeakUnknownBlock(){var a=New();var b=ContractJson.Copy(a);b.Couriers=b.Couriers! with{Conditions=[new(1,NationalRoutes.Edges.First(e=>NationalRoutes.Sea(e.Id)).Id,true)]};Assert.Throws<InvalidDataException>(()=>TravelWorld.Move(a,"request:no-sea",Mainland,true));Assert.Equal(ContractJson.Write(TravelWorld.Move(a,"request:quote",Mainland)),ContractJson.Write(TravelWorld.Move(b,"request:quote",Mainland)));}
    [Theory][InlineData(0)][InlineData(1001)][InlineData(-1)]public void InvalidFareRulesRejected(long fee){Assert.Throws<InvalidDataException>(()=>New(fee));}
    [Fact]public void UnknownPolicyRejected(){var w=New();w.NewGame=w.NewGame! with{VoyageRules=VoyageExpense.Standard with{Policy="unknown"}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData("amount")][InlineData("payee")][InlineData("time")][InlineData("duplicate")][InlineData("missing")][InlineData("revision")]
    public void AlteredPaymentSaveRejected(string change){var w=Arrive().DiagnosticSnapshot();var p=w.VoyageExpenses!.Payments[0];w.VoyageExpenses=w.VoyageExpenses with{Payments=change=="missing"?[]:change=="duplicate"?[p,p]:[change switch{"amount"=>p with{Amount=11},"payee"=>p with{Payee=Player},"revision"=>p with{Revision=1},_=>p with{At=p.At-1}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void GenerationSaveRestoresWaitingBoardedArrivedAndNoMoney(int phase){var s=new WorldSession(New(phase==3?1000:10));var j=Start(s,Mainland);long board=BoardAt(s,j);At(s,phase==0?board-1:phase==1?board: j.Legs[^1].EndAt+2);if(phase==3){j=Start(s,Island);At(s,BoardAt(s,j)+1);}s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"voyage-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New(phase==3?1000:10)));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));At(s,s.Seconds+10000);At(host.Current,host.Current.Seconds+10000);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));}
    [Fact]public void StartProfilePinsRulesAndOldProfileStillBuilds(){var w=New();var d=w.NewGame!;var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"voyage-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(d.Start,d.Registered,d.Selected.Value,42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:NewGameWork.Policy,voyageRules:VoyageExpense.Standard);Assert.Equal(10,store.Read(p.Instance).VoyageRules!.FarePerPassage);Assert.Equal(p.InitialHash,ContractJson.CanonicalHash(NewCampaignStore.Build(p)));var old=store.New(d.Start,d.Registered,d.Selected.Value,42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current);Assert.Null(store.Read(old.Instance).VoyageRules);}

    [Fact]public void ZeroMoneyCanWalkToAnIssuerAndEarnFromExistingWork()
    {
        var s=Arrive(1000);var sea=Start(s,Island);At(s,BoardAt(s,sea)+1);var w=s.DiagnosticSnapshot();var reachable=new HashSet<string>{Mainland};bool changed=true;while(changed){changed=false;foreach(var e in BranchRoutes.GraphEdges(w).Where(e=>!NationalRoutes.Sea(e.Id))){if(reachable.Contains(e.From))changed|=reachable.Add(e.To);if(reachable.Contains(e.To))changed|=reachable.Add(e.From);}}
        var goal=w.NewGame!.Start.People.Where(p=>p.Id!=Player.Value&&reachable.Contains(NewGameWorld.Node(p.Site))).OrderBy(p=>p.Site,StringComparer.Ordinal).First();var trip=Start(s,NewGameWorld.Node(goal.Site),true);At(s,trip.Legs[^1].EndAt+2);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));
        Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:work-when-poor"),s.Revision).Code);At(s,s.Seconds+1);var task=s.DiagnosticSnapshot().Tasks.Last();foreach(var m in s.GetActorView(Player).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(Player,m.Id,s.Revision);Assert.Equal(ResultCode.Accepted,s.Assent(task.Id,Player,true,s.Revision).Code);At(s,s.Seconds+10);foreach(var m in s.GetActorView(Player).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(Player,m.Id,s.Revision);Assert.Equal(ResultCode.Accepted,s.CollectWorkPayment(new("payment:earned-after-fare"),task.Id,Player,s.Revision).Code);Assert.Equal(20,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));
    }
    [Fact]public void BorrowedPurseNeverPaysFareWhenOwnWalletIsEmpty()
    {
        var people=new[]{new RegisteredOfficer(Player.Value,null,"運び手",1520,new(50,50,50,50),StartTemplate.Retainer,RegionalCampaign.Site(Island).Value,"person:shingen",null),new RegisteredOfficer("created:purse-owner",null,"荷主",1520,new(50,50,50,50),StartTemplate.Retainer,RegionalCampaign.Site(Island).Value,"person:shingen",null)};var rows=NewGameWorld.Normalize(people);var setup=NewGameSetup.Preview(NewGameWorld.Scenario(HistoricalStartCatalog.Current),new(rows,[]));Assert.True(setup.IsEligible());var s=new WorldSession(NewGameWorld.Create(setup.World!,rows,Player.Value,42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:NewGameWork.Policy,voyageRules:VoyageExpense.Standard with{FarePerPassage=1000}));
        var id=new EntityId("job:borrowed-for-voyage");Assert.Equal(ResultCode.Accepted,s.RequestTransport(id,s.Revision).Code);foreach(var action in new[]{HandoverAction.Accept,HandoverAction.Collect}){var j=TransportWork.Jobs(s.DiagnosticSnapshot()).Single();var t=j.Handover.Terms;var op=new EntityId("operation:purse/"+s.Revision);var i=new HandoverInput(op,action,Player,t.Source,t.Issuer,action==HandoverAction.Collect?new EntityId("transfer:transport/"+op.Value.Replace(':','/')):null,s.Seconds,j.Handover.Entries.Length);Assert.Equal(ResultCode.Accepted,s.HandoverTransport(id,i,s.Revision).Code);}
        var trip=Start(s,Mainland);At(s,trip.Legs[^1].EndAt+2);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));trip=Start(s,Island);At(s,BoardAt(s,trip)+1);var w=s.DiagnosticSnapshot();var cargo=w.ResourceLots.Single(l=>l.Id==TransportWork.Cargo(id));Assert.Equal(100,cargo.Quantity);Assert.Equal(new EntityId("created:purse-owner"),cargo.Owner);Assert.Single(w.VoyageExpenses!.Refusals);
    }
    [Fact]public void AfterBoardingCannotCancelForARefund(){var s=new WorldSession(New());var j=Start(s,Mainland);At(s,BoardAt(s,j));Assert.Throws<InvalidDataException>(()=>TravelControl.Prepare(s.DiagnosticSnapshot(),new(new("request:late-cancel"),Player,j.Task,null)));Assert.Equal(990,NewGameWork.Balance(s.DiagnosticSnapshot(),Player));}
    [Fact]public void CancelledGenerationRestoreNeverChargesLater(){var s=new WorldSession(New());Start(s,Mainland);Assert.Equal(ResultCode.Accepted,s.ChangeTravel(TravelControl.Request(s.DiagnosticSnapshot(),"request:cancel-save",null),s.Revision).Code);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"voyage-cancel-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId,new(0,1));var host=new WorldSessionHost(new(New()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));At(s,10000);At(host.Current,10000);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(host.Current.DiagnosticSnapshot()));Assert.Null(host.Current.DiagnosticSnapshot().VoyageExpenses);}
    [Fact]public void WalkPreferenceIsSavedAndCannotBeChangedUnderTheSameId(){var s=Arrive();var e=BranchRoutes.GraphEdges(s.DiagnosticSnapshot()).First(e=>!NationalRoutes.Sea(e.Id)&&(e.From==Mainland||e.To==Mainland));var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:walk-immutable",e.From==Mainland?e.To:e.From,true);Assert.Equal(VoyageExpense.WalkOnly,i.RoutePolicy);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(i with{RoutePolicy=null},s.Revision).Code);s=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));Assert.Equal(VoyageExpense.WalkOnly,s.DiagnosticSnapshot().Requests.Last().Intent.RoutePolicy);}
    [Fact]public void FarePolicyCannotBeAddedWithoutPrivateWallets(){var w=New();var d=w.NewGame!;Assert.Throws<InvalidDataException>(()=>NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,voyageRules:VoyageExpense.Standard));}
    [Fact]public void OldProfileCannotForgeWalkPolicyIntoSavedOriginal(){var s=new WorldSession(New(enabled:false));var i=TravelWorld.Move(s.DiagnosticSnapshot(),"request:legacy-route",Mainland);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);var w=s.DiagnosticSnapshot();var changed=i with{RoutePolicy=VoyageExpense.WalkOnly};w.Requests=[w.Requests.Single() with{Intent=changed,BodyHash=ContractJson.CanonicalHash(changed)}];Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
